const nw = msg.data.new_state;
const ow = msg.data.old_state;
if (!nw || !nw.attributes || !nw.attributes.uwagi) return null;

const noweUwagi = nw.attributes.uwagi;
// Pamięć osobno dla każdej encji (kilkoro dzieci w jednym węźle).
const cacheKey = 'uwagi_id_cache_' + nw.entity_id.replace(/\./g, '_');
let stareUwagi = context.get(cacheKey) || (ow && ow.attributes && ow.attributes.uwagi) || [];
context.set(cacheKey, noweUwagi);

const fn = nw.attributes.friendly_name || "";
const imie = fn.includes(': ') ? fn.split(': ').pop() : "Uczeń";
let wiadomosci = [];

noweUwagi.forEach(n => {
    const juzBylo = stareUwagi.some(o => String(o.id) === String(n.id));
    if (!juzBylo) {
        let emoji = n.typ === 'pozytywna' ? '🌟' : (n.typ === 'negatywna' ? '⚠️' : 'ℹ️');
        wiadomosci.push({
            payload: {
                title: `Nowy wpis w dzienniku: ${imie}`,
                message: `### ${emoji} ${n.kategoria}\n**Data:** ${n.data}\n**Treść:** ${n.tresc}\n\n---\n**Autor:** ${n.autor}`,
                notification_id: "vultron_uwaga_" + n.id
            }
        });
    }
});

if (wiadomosci.length > 0) return [wiadomosci];
return null;
